{
  "name": "FarmaSalud AI",
  "description": "Una plataforma farmacéutica moderna con asistente de salud inteligente impulsado por Gemini, análisis de recetas por visión artificial y gestión de medicamentos.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("No se pudo encontrar el elemento raíz para montar la aplicación");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Category {
  PAINKILLERS = 'Analgésicos',
  ANTIBIOTICS = 'Antibióticos',
  VITAMINS = 'Vitaminas',
  SKINCARE = 'Cuidado de la piel',
  DIGESTIVE = 'Digestivo',
  OTHERS = 'Otros'
}

export interface Medication {
  id: string;
  name: string;
  genericName: string;
  description: string;
  price: number;
  category: Category;
  imageUrl: string;
  stock: number;
  usage: string;
  sideEffects: string;
}

export interface CartItem extends Medication {
  quantity: number;
}

export interface PrescriptionAnalysis {
  medications: string[];
  dosage: string;
  isAuthentic: boolean;
  warnings: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

export const getGeminiHealthAdvice = async (query: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Eres un asistente farmacéutico experto. Responde a la siguiente duda de salud de forma profesional, clara y siempre incluyendo un aviso de que no sustituyes a un médico: "${query}"`,
    });
    return response.text || "Lo siento, no pude procesar tu solicitud en este momento.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Hubo un error al consultar con el asistente de salud.";
  }
};

export const analyzePrescription = async (base64Data: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Data } },
          { text: "Analiza esta receta médica. Extrae los nombres de los medicamentos, la dosificación indicada y cualquier advertencia importante. Devuelve la respuesta en formato JSON claro." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            medications: { type: Type.ARRAY, items: { type: Type.STRING } },
            dosage: { type: Type.STRING },
            warnings: { type: Type.STRING },
            isAuthentic: { type: Type.BOOLEAN, description: "¿Parece una receta médica real?" }
          },
          required: ["medications", "dosage", "warnings", "isAuthentic"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("Prescription Analysis Error:", error);
    throw error;
  }
};

