import React, { useState, useMemo } from 'react';
import { Search, ShoppingBag, Plus, Minus, Trash2, CheckCircle2, User, Stethoscope } from 'lucide-react';
import { Medication, SaleItem } from '../types';

interface PosSystemProps {
  medications: Medication[];
  onCompleteSale: (items: SaleItem[]) => void;
}

const PosSystem: React.FC<PosSystemProps> = ({ medications, onCompleteSale }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [customerName, setCustomerName] = useState('');

  const filteredMeds = medications.filter(m => 
    m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.genericName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const total = useMemo(() => cart.reduce((sum, item) => sum + (item.price * item.quantity), 0), [cart]);

  const addToCart = (med: Medication) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === med.id);
      if (existing) {
        return prev.map(item => item.id === med.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...med, quantity: 1 }];
    });
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        return { ...item, quantity: Math.max(0, item.quantity + delta) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const handleComplete = () => {
    if (cart.length === 0) return;
    onCompleteSale(cart);
    setCart([]);
    setCustomerName('');
    alert('Venta registrada con éxito');
  };

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden">
      {/* Product Selection Area */}
      <div className="flex-1 overflow-y-auto p-8 bg-slate-50/50">
        <div className="mb-8">
          <h2 className="text-2xl font-black text-slate-800">Nueva Venta</h2>
          <p className="text-slate-500">Selecciona los productos para el cliente.</p>
        </div>

        <div className="relative mb-8">
          <input 
            type="text" 
            placeholder="Buscar por nombre o componente..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl shadow-sm focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all outline-none"
          />
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredMeds.map(med => (
            <button 
              key={med.id}
              onClick={() => addToCart(med)}
              className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md hover:border-emerald-200 text-left transition-all group relative overflow-hidden"
            >
              <div className="flex items-start justify-between mb-4">
                <div className="w-16 h-16 rounded-2xl overflow-hidden border border-slate-100 shrink-0">
                  <img src={med.imageUrl} className="w-full h-full object-cover" />
                </div>
                <div className="bg-emerald-50 text-emerald-600 p-2 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity">
                  <Plus className="w-4 h-4" />
                </div>
              </div>
              <div className="text-xs font-bold text-emerald-600 mb-1 uppercase tracking-wider">{med.category}</div>
              <h3 className="font-black text-slate-800 leading-tight mb-1">{med.name}</h3>
              <p className="text-xs text-slate-400 mb-4">{med.genericName}</p>
              <div className="flex items-center justify-between">
                <span className="text-lg font-black text-slate-900">${med.price.toFixed(2)}</span>
                <span className={`text-[10px] font-bold ${med.stock < 10 ? 'text-rose-500' : 'text-slate-400'}`}>
                  Stock: {med.stock}
                </span>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Summary Side Panel */}
      <div className="w-96 bg-white border-l border-slate-100 flex flex-col shadow-2xl z-10">
        <div className="p-6 border-b border-slate-100">
          <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
            <ShoppingBag className="w-6 h-6 text-emerald-600" />
            Venta Actual
          </h3>
        </div>

        <div className="p-6 border-b border-slate-100 space-y-4">
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Cliente (Opcional)</label>
            <div className="relative">
              <input 
                type="text" 
                value={customerName}
                onChange={(e) => setCustomerName(e.target.value)}
                placeholder="Nombre del cliente..."
                className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-emerald-500/20 outline-none"
              />
              <User className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
              <ShoppingBag className="w-16 h-16 text-slate-200 mb-4" />
              <p className="font-bold text-slate-400">Sin productos seleccionados</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex gap-4">
                <div className="flex-1">
                  <h4 className="font-bold text-slate-800 text-sm leading-tight mb-1">{item.name}</h4>
                  <p className="text-[10px] text-slate-400 mb-2">${item.price.toFixed(2)} / ud.</p>
                  <div className="flex items-center gap-4">
                    <div className="flex items-center gap-3 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">
                      <button onClick={() => updateQuantity(item.id, -1)} className="p-1 text-slate-400 hover:text-emerald-600">
                        <Minus className="w-3 h-3" />
                      </button>
                      <span className="text-xs font-black text-slate-800 w-4 text-center">{item.quantity}</span>
                      <button onClick={() => updateQuantity(item.id, 1)} className="p-1 text-slate-400 hover:text-emerald-600">
                        <Plus className="w-3 h-3" />
                      </button>
                    </div>
                    <button onClick={() => updateQuantity(item.id, -item.quantity)} className="text-slate-300 hover:text-rose-500">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
                <div className="text-right">
                  <div className="font-black text-slate-800 text-sm">${(item.price * item.quantity).toFixed(2)}</div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-8 bg-slate-50/50 border-t border-slate-100 space-y-6">
          <div className="space-y-2">
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Subtotal</span>
              <span>${total.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Impuestos (0%)</span>
              <span>$0.00</span>
            </div>
            <div className="flex justify-between items-end pt-4">
              <span className="text-slate-400 font-bold uppercase text-[10px] tracking-widest">Total a Pagar</span>
              <span className="text-3xl font-black text-slate-900">${total.toFixed(2)}</span>
            </div>
          </div>

          <button 
            onClick={handleComplete}
            disabled={cart.length === 0}
            className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white py-5 rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-900/20"
          >
            Completar Venta
            <CheckCircle2 className="w-6 h-6" />
          </button>
        </div>
      </div>
    </div>
  );
};

