import React, { useState } from 'react';
import { MOCK_MEDICATIONS } from './constants';
import { Medication, User, SaleItem } from './types';
import Login from './components/Login';
import PosSystem from './components/PosSystem';
import InventoryManager from './components/InventoryManager';
import AIConsultant from './components/AIConsultant';
import { HeartPulse, LayoutDashboard, ShoppingCart, Pill, LogOut, Bot, Settings, Users } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [medications, setMedications] = useState<Medication[]>(MOCK_MEDICATIONS);
  const [isAIConsultantOpen, setIsAIConsultantOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'POS' | 'INVENTORY'>('POS');

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab(user.role === 'ADMIN' ? 'INVENTORY' : 'POS');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addMedication = (newMed: Medication) => {
    setMedications([...medications, newMed]);
  };

  const updateMedication = (updatedMed: Medication) => {
    setMedications(medications.map(m => m.id === updatedMed.id ? updatedMed : m));
  };

  const deleteMedication = (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      setMedications(medications.filter(m => m.id !== id));
    }
  };

  const handleCompleteSale = (items: SaleItem[]) => {
    // Restar stock
    const updatedMeds = medications.map(med => {
      const soldItem = items.find(item => item.id === med.id);
      if (soldItem) {
        return { ...med, stock: Math.max(0, med.stock - soldItem.quantity) };
      }
      return med;
    });
    setMedications(updatedMeds);
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex">
      {/* Navigation Sidebar */}
