            <span className="text-white font-black text-lg hidden lg:block tracking-tight">FarmaSalud <span className="text-emerald-500 text-xs block">SYSTEM V1.0</span></span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          {currentUser.role === 'EMPLOYEE' || currentUser.role === 'ADMIN' ? (
            <button 
