              className={`w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all ${activeTab === 'POS' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
            >
              <ShoppingCart className="w-6 h-6" />
              <span className="font-bold hidden lg:block">Punto de Venta</span>
            </button>
          ) : null}

          {currentUser.role === 'ADMIN' && (
            <button 
              onClick={() => setActiveTab('INVENTORY')}
              className={`w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all ${activeTab === 'INVENTORY' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
            >
              <Pill className="w-6 h-6" />
              <span className="font-bold hidden lg:block">Inventario</span>
