          >
            <Bot className="w-6 h-6" />
            <span className="font-bold hidden lg:block">Asistente IA</span>
          </button>
        </nav>

        <div className="p-4 mt-auto border-t border-white/5">
          <div className="flex items-center gap-3 p-4 bg-white/5 rounded-2xl mb-4 hidden lg:flex">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/20 flex items-center justify-center text-emerald-500 font-bold">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-white font-bold text-sm truncate">{currentUser.name}</p>
              <p className="text-slate-500 text-[10px] uppercase font-black">{currentUser.role}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-rose-400 hover:bg-rose-400/10 transition-all"
          >
            <LogOut className="w-6 h-6" />
            <span className="font-bold hidden lg:block">Cerrar Sesión</span>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <div className="flex items-center gap-2 text-slate-400">
            <LayoutDashboard className="w-4 h-4" />
            <span className="text-xs font-bold uppercase tracking-widest">{activeTab}</span>
          </div>
          <div className="flex items-center gap-4">
            <div className="h-8 w-px bg-slate-100"></div>
            <span className="text-xs font-bold text-slate-400">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'POS' ? (
            <PosSystem medications={medications} onCompleteSale={handleCompleteSale} />
          ) : (
            <div className="h-full overflow-y-auto">
              <InventoryManager 
                medications={medications} 
                onAdd={addMedication} 
                onUpdate={updateMedication} 
                onDelete={deleteMedication}
              />
            </div>
          )}
        </div>
      </main>

      {/* Overlays */}
      {isAIConsultantOpen && <AIConsultant onClose={() => setIsAIConsultantOpen(false)} />}
    </div>
  );
};

