import React, { useState, useMemo } from 'react';
import { Search, ShoppingBag, Plus, Minus, Trash2, CheckCircle2, User, FileText, AlertCircle, ShieldCheck } from 'lucide-react';
import { Medication, SaleItem, InsurancePlan, PrescriptionData } from '../types';
import { INSURANCE_PLANS } from '../constants';

interface PosSystemProps {
  medications: Medication[];
  onCompleteSale: (items: SaleItem[], insurance: InsurancePlan, prescription?: PrescriptionData) => void;
}

const PosSystem: React.FC<PosSystemProps> = ({ medications, onCompleteSale }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedInsurance, setSelectedInsurance] = useState<InsurancePlan>(INSURANCE_PLANS[0]);
  const [prescription, setPrescription] = useState<PrescriptionData>({ doctorLicense: '', patientName: '', date: new Date().toISOString().split('T')[0] });

  const filteredMeds = medications.filter(m => 
    m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.genericName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    m.laboratory.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const subtotal = useMemo(() => cart.reduce((sum, item) => sum + item.subtotal, 0), [cart]);
  const discount = useMemo(() => subtotal * (selectedInsurance.coveragePercent / 100), [subtotal, selectedInsurance]);
  const total = subtotal - discount;

  const addToCart = (med: Medication, isFractional: boolean) => {
    setCart(prev => {
      const existing = prev.find(item => item.medication.id === med.id && item.isFractional === isFractional);
      const price = isFractional ? med.priceUnit : med.priceBox;

      if (existing) {
        return prev.map(item => 
          (item.medication.id === med.id && item.isFractional === isFractional) 
            ? { ...item, quantity: item.quantity + 1, subtotal: (item.quantity + 1) * price } 
            : item
        );
      }
      return [...prev, { 
        medication: med, 
        quantity: 1, 
        isFractional, 
        selectedBatch: med.batches[0]?.lotNumber || 'N/A', 
        subtotal: price 
      }];
    });
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const handleComplete = () => {
    const needsPrescription = cart.some(item => item.medication.isControlled);
    if (needsPrescription && (!prescription.doctorLicense || !prescription.patientName)) {
      alert("Atención: Venta bloqueada. Se requiere completar los datos de la receta para medicamentos controlados.");
      return;
    }
    onCompleteSale(cart, selectedInsurance, needsPrescription ? prescription : undefined);
    setCart([]);
    setPrescription({ doctorLicense: '', patientName: '', date: '' });
  };

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-slate-100">
      {/* Area de búsqueda y catálogo */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="p-6 bg-white border-b border-slate-200">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Buscar por Nombre, Monodroga o Laboratorio..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-lg font-medium"
            />
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-6 h-6" />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredMeds.map(med => (
            <div key={med.id} className="bg-white rounded-3xl p-5 border border-slate-200 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
              <div className="flex justify-between items-start mb-4">
                <div className="px-3 py-1 bg-slate-100 rounded-full text-[10px] font-bold text-slate-500 uppercase">{med.laboratory}</div>
                {med.isControlled && <div className="px-3 py-1 bg-rose-100 text-rose-600 rounded-full text-[10px] font-black uppercase flex items-center gap-1"><AlertCircle className="w-3 h-3"/> Venta Bajo Receta</div>}
              </div>
              <h3 className="text-xl font-black text-slate-800 leading-tight mb-1">{med.name}</h3>
              <p className="text-sm text-slate-400 font-medium mb-4 italic">{med.genericName}</p>

              <div className="space-y-3">
                <button 
                  onClick={() => addToCart(med, false)}
                  className="w-full flex justify-between items-center p-3 bg-emerald-50 rounded-2xl hover:bg-emerald-100 transition-colors group"
                >
                  <span className="text-sm font-bold text-emerald-700">Caja ({med.unitsPerBox} uds)</span>
                  <span className="font-black text-emerald-800">${med.priceBox} <Plus className="inline w-4 h-4 ml-1 opacity-0 group-hover:opacity-100 transition-opacity"/></span>
                </button>
                <button 
                  onClick={() => addToCart(med, true)}
                  className="w-full flex justify-between items-center p-3 bg-blue-50 rounded-2xl hover:bg-blue-100 transition-colors group"
                >
                  <span className="text-sm font-bold text-blue-700">Unidad Fraccionada</span>
                  <span className="font-black text-blue-800">${med.priceUnit} <Plus className="inline w-4 h-4 ml-1 opacity-0 group-hover:opacity-100 transition-opacity"/></span>
                </button>
              </div>
              <div className="mt-4 pt-4 border-t border-slate-50 flex items-center justify-between text-[10px] font-bold text-slate-400">
                <span>STOCK: {med.stockBoxes} C / {med.stockUnits} U</span>
                <span className={med.batches[0]?.expiryDate < '2024-01-01' ? 'text-rose-500' : ''}>VENCE: {med.batches[0]?.expiryDate}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Panel de Venta / Resumen */}
      <div className="w-[400px] bg-white border-l border-slate-200 flex flex-col shadow-2xl">
        <div className="p-6 bg-slate-900 text-white shrink-0">
          <h2 className="text-xl font-black flex items-center gap-2"><ShoppingBag className="text-emerald-400"/> Resumen de Venta</h2>
        </div>

        {/* Configuración de Seguro */}
        <div className="p-4 bg-slate-50 border-b border-slate-200">
          <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Plan de Cobertura</label>
          <div className="flex flex-wrap gap-2">
            {INSURANCE_PLANS.map(plan => (
              <button
                key={plan.id}
                onClick={() => setSelectedInsurance(plan)}
                className={`px-3 py-2 rounded-xl text-xs font-bold transition-all ${selectedInsurance.id === plan.id ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/30' : 'bg-white text-slate-500 border border-slate-200'}`}
              >
                {plan.name}
              </button>
            ))}
          </div>
        </div>

        {/* Lista de Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-20 italic">
              <ShoppingBag className="w-12 h-12 mb-2"/>
              <p>Esperando selección...</p>
            </div>
          ) : (
            cart.map((item, i) => (
              <div key={i} className="bg-slate-50 rounded-2xl p-4 border border-slate-100 relative group">
                <button onClick={() => removeFromCart(i)} className="absolute -top-2 -right-2 bg-rose-500 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="w-3 h-3"/></button>
                <div className="flex justify-between items-start mb-1">
                  <h4 className="font-bold text-slate-800 text-sm">{item.medication.name}</h4>
                  <span className="font-black text-slate-900">${item.subtotal}</span>
                </div>
                <div className="flex items-center justify-between text-[10px]">
                  <span className="text-slate-400 font-medium">{item.isFractional ? '1 Unidad' : '1 Caja'}</span>
                  <span className="bg-slate-200 px-2 rounded font-mono">LOTE: {item.selectedBatch}</span>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Datos de Receta (Condicional) */}
        {cart.some(i => i.medication.isControlled) && (
          <div className="p-4 bg-rose-50 border-t border-rose-100">
            <h5 className="text-[10px] font-black text-rose-500 uppercase flex items-center gap-1 mb-3"><FileText className="w-3 h-3"/> Validación de Receta Obligatoria</h5>
            <div className="space-y-3">
              <input 
                placeholder="Nombre del Paciente" 
                value={prescription.patientName}
                onChange={e => setPrescription({...prescription, patientName: e.target.value})}
                className="w-full p-2 text-xs border border-rose-200 rounded-lg outline-none focus:ring-2 focus:ring-rose-500/20"
              />
              <input 
                placeholder="Matrícula del Médico" 
                value={prescription.doctorLicense}
                onChange={e => setPrescription({...prescription, doctorLicense: e.target.value})}
                className="w-full p-2 text-xs border border-rose-200 rounded-lg outline-none focus:ring-2 focus:ring-rose-500/20"
              />
            </div>
          </div>
        )}

        {/* Totales y Finalizar */}
        <div className="p-6 bg-slate-50 border-t border-slate-200 space-y-3">
          <div className="flex justify-between text-xs font-bold text-slate-400">
            <span>Subtotal Bruto</span>
            <span>${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-xs font-bold text-emerald-600">
            <span>Descuento {selectedInsurance.name}</span>
            <span>- ${discount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-end py-2">
            <span className="text-slate-900 font-black text-lg">TOTAL NETO</span>
            <span className="text-3xl font-black text-emerald-700">${total.toFixed(2)}</span>
          </div>
          <button 
            onClick={handleComplete}
            disabled={cart.length === 0}
            className="w-full bg-slate-900 hover:bg-black text-white py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all disabled:opacity-20"
          >
            Finalizar Cobro <CheckCircle2 className="w-6 h-6 text-emerald-400"/>
          </button>
        </div>
      </div>
    </div>
  );
};

export default PosSystem;

