            <button className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 transition-all shadow-lg shadow-emerald-600/20">
              <Plus className="w-5 h-5"/> Nuevo Ingreso
            </button>
          </div>
        </header>

        <div className="grid grid-cols-1 gap-6">
          {filtered.map(med => (
            <div key={med.id} className="bg-white rounded-3xl p-6 border border-slate-200 shadow-sm flex flex-col lg:flex-row gap-8 items-start lg:items-center">
              <div className="flex items-center gap-4 min-w-[300px]">
                <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center border border-slate-100 shrink-0">
                  <Pill className="w-8 h-8 text-emerald-600"/>
