                </div>
              </div>

              <div className="flex-1 grid grid-cols-2 md:grid-cols-4 gap-6 w-full">
                <div className="text-center md:text-left">
                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest block mb-1">Precio Caja</span>
                  <span className="text-lg font-black text-slate-800">${med.priceBox}</span>
                </div>
                <div className="text-center md:text-left">
                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest block mb-1">Precio Unit</span>
                  <span className="text-lg font-black text-slate-800">${med.priceUnit}</span>
