import React, { useState } from 'react';
import { MOCK_MEDICATIONS } from './constants';
import { Medication, User, SaleItem } from './types';
import Login from './components/Login';
import PosSystem from './components/PosSystem';
import InventoryManager from './components/InventoryManager';
import AIConsultant from './components/AIConsultant';
import { HeartPulse, LayoutDashboard, ShoppingCart, Pill, LogOut, Bot, Settings, Users } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [medications, setMedications] = useState<Medication[]>(MOCK_MEDICATIONS);
  const [isAIConsultantOpen, setIsAIConsultantOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'POS' | 'INVENTORY'>('POS');

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab(user.role === 'ADMIN' ? 'INVENTORY' : 'POS');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addMedication = (newMed: Medication) => {
    setMedications([...medications, newMed]);
  };

  const updateMedication = (updatedMed: Medication) => {
    setMedications(medications.map(m => m.id === updatedMed.id ? updatedMed : m));
  };

  const deleteMedication = (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      setMedications(medications.filter(m => m.id !== id));
    }
  };

  const handleCompleteSale = (items: SaleItem[]) => {
    // Restar stock
    const updatedMeds = medications.map(med => {
      // Fixed: item.id does not exist on SaleItem, it's item.medication.id
      // Fixed: Medication uses stockBoxes and stockUnits, not 'stock'
      const soldItemsForMed = items.filter(item => item.medication.id === med.id);

      if (soldItemsForMed.length > 0) {
        let newStockBoxes = med.stockBoxes;
        let newStockUnits = med.stockUnits;

        soldItemsForMed.forEach(soldItem => {
          if (soldItem.isFractional) {
            newStockUnits = Math.max(0, newStockUnits - soldItem.quantity);
          } else {
            newStockBoxes = Math.max(0, newStockBoxes - soldItem.quantity);
          }
        });

        return { ...med, stockBoxes: newStockBoxes, stockUnits: newStockUnits };
      }
      return med;
    });
    setMedications(updatedMeds);
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex">
      {/* Navigation Sidebar */}
      <aside className="w-20 lg:w-64 bg-slate-900 flex flex-col shrink-0 transition-all duration-300">
        <div className="p-6 mb-8">
          <div className="flex items-center gap-3">
            <div className="bg-emerald-600 p-2 rounded-xl shrink-0 shadow-lg shadow-emerald-900/40">
              <HeartPulse className="text-white w-6 h-6" />
            </div>
            <span className="text-white font-black text-lg hidden lg:block tracking-tight">FarmaSalud <span className="text-emerald-500 text-xs block">SYSTEM V1.0</span></span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          {currentUser.role === 'EMPLOYEE' || currentUser.role === 'ADMIN' ? (
            <button 
              onClick={() => setActiveTab('POS')}
              className={`w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all ${activeTab === 'POS' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
            >
              <ShoppingCart className="w-6 h-6" />
              <span className="font-bold hidden lg:block">Punto de Venta</span>
            </button>
          ) : null}

          {currentUser.role === 'ADMIN' && (
            <button 
              onClick={() => setActiveTab('INVENTORY')}
              className={`w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all ${activeTab === 'INVENTORY' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
            >
              <Pill className="w-6 h-6" />
              <span className="font-bold hidden lg:block">Inventario</span>
            </button>
          )}

          <div className="pt-8 opacity-20 border-t border-white/10 mx-4"></div>

          <button 
            onClick={() => setIsAIConsultantOpen(true)}
            className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-slate-400 hover:text-emerald-400 hover:bg-white/5 transition-all"
          >
            <Bot className="w-6 h-6" />
            <span className="font-bold hidden lg:block">Asistente IA</span>
          </button>
        </nav>

        <div className="p-4 mt-auto border-t border-white/5">
          <div className="flex items-center gap-3 p-4 bg-white/5 rounded-2xl mb-4 hidden lg:flex">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/20 flex items-center justify-center text-emerald-500 font-bold">
              {currentUser.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-white font-bold text-sm truncate">{currentUser.name}</p>
              <p className="text-slate-500 text-[10px] uppercase font-black">{currentUser.role}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-rose-400 hover:bg-rose-400/10 transition-all"
          >
            <LogOut className="w-6 h-6" />
            <span className="font-bold hidden lg:block">Cerrar Sesión</span>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-8 shrink-0">
          <div className="flex items-center gap-2 text-slate-400">
            <LayoutDashboard className="w-4 h-4" />
            <span className="text-xs font-bold uppercase tracking-widest">{activeTab}</span>
          </div>
          <div className="flex items-center gap-4">
            <div className="h-8 w-px bg-slate-100"></div>
            <span className="text-xs font-bold text-slate-400">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
          </div>
        </header>

        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'POS' ? (
            <PosSystem medications={medications} onCompleteSale={handleCompleteSale} />
          ) : (
            <div className="h-full overflow-y-auto">
              <InventoryManager 
                medications={medications} 
                onAdd={addMedication} 
                onUpdate={updateMedication} 
                onDelete={deleteMedication}
              />
            </div>
          )}
        </div>
      </main>

      {/* Overlays */}
      {isAIConsultantOpen && <AIConsultant onClose={() => setIsAIConsultantOpen(false)} />}
    </div>
  );
};

export default App;

