    const diffTime = expiry.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { label: 'Vencido', color: 'bg-rose-500' };
    if (diffDays < 90) return { label: 'Próximo', color: 'bg-amber-500' };
