import React, { useState, useMemo } from 'react';
import { Search, ShoppingBag, Plus, Minus, Trash2, CheckCircle2, User, FileText, AlertCircle, ShieldCheck, X, ChevronUp } from 'lucide-react';
import { Medication, SaleItem, InsurancePlan, PrescriptionData } from '../types';
import { INSURANCE_PLANS } from '../constants';

interface PosSystemProps {
  medications: Medication[];
  onCompleteSale: (items: SaleItem[], insurance: InsurancePlan, prescription?: PrescriptionData) => void;
}

const PosSystem: React.FC<PosSystemProps> = ({ medications, onCompleteSale }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedInsurance, setSelectedInsurance] = useState<InsurancePlan>(INSURANCE_PLANS[0]);
  const [prescription, setPrescription] = useState<PrescriptionData>({ doctorLicense: '', patientName: '', date: new Date().toISOString().split('T')[0] });
  const [isCartMobileOpen, setIsCartMobileOpen] = useState(false);

  const filteredMeds = medications.filter(m => 
    m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.genericName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    m.laboratory.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const subtotal = useMemo(() => cart.reduce((sum, item) => sum + item.subtotal, 0), [cart]);
  const discount = useMemo(() => subtotal * (selectedInsurance.coveragePercent / 100), [subtotal, selectedInsurance]);
  const total = subtotal - discount;

  const addToCart = (med: Medication, isFractional: boolean) => {
    setCart(prev => {
      const existing = prev.find(item => item.medication.id === med.id && item.isFractional === isFractional);
      const price = isFractional ? med.priceUnit : med.priceBox;

      if (existing) {
        return prev.map(item => 
          (item.medication.id === med.id && item.isFractional === isFractional) 
            ? { ...item, quantity: item.quantity + 1, subtotal: (item.quantity + 1) * price } 
            : item
        );
      }
      return [...prev, { 
        medication: med, 
        quantity: 1, 
        isFractional, 
        selectedBatch: med.batches[0]?.lotNumber || 'N/A', 
        subtotal: price 
      }];
    });
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const handleComplete = () => {
    const needsPrescription = cart.some(item => item.medication.isControlled);
    if (needsPrescription && (!prescription.doctorLicense || !prescription.patientName)) {
      alert("Atención: Venta bloqueada. Se requiere completar los datos de la receta para medicamentos controlados.");
      return;
    }
    onCompleteSale(cart, selectedInsurance, needsPrescription ? prescription : undefined);
    setCart([]);
    setPrescription({ doctorLicense: '', patientName: '', date: '' });
    setIsCartMobileOpen(false);
  };

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-slate-100">
      {/* Area de búsqueda y catálogo */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="p-4 md:p-6 bg-white border-b border-slate-200 sticky top-0 z-10">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Buscar medicamentos..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 md:pl-12 pr-4 py-3 md:py-4 bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl focus:ring-4 focus:ring-emerald-500/10 outline-none transition-all text-sm md:text-lg font-medium"
            />
            <Search className="absolute left-3 md:left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 md:w-6 md:h-6" />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 md:gap-6 pb-24 lg:pb-6">
          {filteredMeds.map(med => (
            <div key={med.id} className="bg-white rounded-2xl md:rounded-3xl p-4 md:p-5 border border-slate-200 shadow-sm hover:shadow-xl transition-all">
              <div className="flex justify-between items-start mb-3">
                <div className="px-2 py-0.5 bg-slate-100 rounded-full text-[9px] font-bold text-slate-500 uppercase">{med.laboratory}</div>
                {med.isControlled && <div className="px-2 py-0.5 bg-rose-100 text-rose-600 rounded-full text-[9px] font-black uppercase flex items-center gap-1"><AlertCircle className="w-2.5 h-2.5"/> Controlado</div>}
              </div>
              <h3 className="text-lg md:text-xl font-black text-slate-800 leading-tight mb-1">{med.name}</h3>
              <p className="text-xs text-slate-400 font-medium mb-4 italic">{med.genericName}</p>

              <div className="space-y-2 md:space-y-3">
                <button 
                  onClick={() => addToCart(med, false)}
                  className="w-full flex justify-between items-center p-2.5 md:p-3 bg-emerald-50 rounded-xl md:rounded-2xl hover:bg-emerald-100 transition-colors"
                >
                  <span className="text-xs font-bold text-emerald-700">Caja</span>
                  <span className="font-black text-emerald-800 text-sm md:text-base">${med.priceBox}</span>
                </button>
                <button 
                  onClick={() => addToCart(med, true)}
                  className="w-full flex justify-between items-center p-2.5 md:p-3 bg-blue-50 rounded-xl md:rounded-2xl hover:bg-blue-100 transition-colors"
                >
                  <span className="text-xs font-bold text-blue-700">Unidad</span>
                  <span className="font-black text-blue-800 text-sm md:text-base">${med.priceUnit}</span>
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Panel de Venta / Resumen - Desktop Sidebar / Mobile Drawer */}
      <div className={`
        fixed lg:relative inset-x-0 bottom-0 lg:inset-auto z-[80] lg:z-10
        w-full lg:w-[400px] bg-white border-l border-slate-200 flex flex-col shadow-2xl transition-transform duration-300 transform
        ${isCartMobileOpen ? 'translate-y-0 h-[80vh]' : 'translate-y-full h-0 lg:translate-y-0 lg:h-full'}
      `}>
        <div className="p-4 md:p-6 bg-slate-900 text-white shrink-0 flex justify-between items-center">
          <h2 className="text-lg md:text-xl font-black flex items-center gap-2">
            <ShoppingBag className="text-emerald-400 w-5 h-5 md:w-6 md:h-6"/> 
            Resumen de Venta
          </h2>
          <button onClick={() => setIsCartMobileOpen(false)} className="lg:hidden p-2 hover:bg-white/10 rounded-full">
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Configuración de Seguro */}
        <div className="p-3 md:p-4 bg-slate-50 border-b border-slate-200 overflow-x-auto scrollbar-hide">
          <div className="flex gap-2 min-w-max lg:min-w-0 lg:flex-wrap">
            {INSURANCE_PLANS.map(plan => (
              <button
                key={plan.id}
                onClick={() => setSelectedInsurance(plan)}
                className={`px-3 py-1.5 md:py-2 rounded-xl text-[10px] md:text-xs font-bold transition-all whitespace-nowrap ${selectedInsurance.id === plan.id ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/30' : 'bg-white text-slate-500 border border-slate-200'}`}
              >
                {plan.name}
              </button>
            ))}
          </div>
        </div>

        {/* Lista de Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center opacity-20 italic py-10">
              <ShoppingBag className="w-10 h-10 mb-2"/>
              <p className="text-sm">Carrito vacío</p>
            </div>
          ) : (
            cart.map((item, i) => (
              <div key={i} className="bg-slate-50 rounded-xl p-3 border border-slate-100 relative">
                <button onClick={() => removeFromCart(i)} className="absolute -top-1 -right-1 bg-rose-500 text-white p-1 rounded-full"><Trash2 className="w-3 h-3"/></button>
                <div className="flex justify-between items-start mb-1">
                  <h4 className="font-bold text-slate-800 text-xs md:text-sm truncate pr-4">{item.medication.name}</h4>
                  <span className="font-black text-slate-900 text-xs md:text-sm shrink-0">${item.subtotal}</span>
                </div>
                <div className="flex items-center justify-between text-[10px]">
                  <span className="text-slate-400 font-medium">{item.isFractional ? '1 Unidad' : '1 Caja'}</span>
                  <span className="bg-slate-200 px-1.5 rounded font-mono">LOTE: {item.selectedBatch}</span>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Totales y Finalizar */}
        <div className="p-4 md:p-6 bg-slate-50 border-t border-slate-200 space-y-2 md:space-y-3">
          <div className="flex justify-between text-[10px] md:text-xs font-bold text-slate-400">
            <span>Subtotal</span>
            <span>${subtotal.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-[10px] md:text-xs font-bold text-emerald-600">
            <span>Dto. {selectedInsurance.name}</span>
            <span>- ${discount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-end py-1">
            <span className="text-slate-900 font-black text-sm md:text-lg">TOTAL</span>
            <span className="text-2xl md:text-3xl font-black text-emerald-700">${total.toFixed(2)}</span>
          </div>
          <button 
            onClick={handleComplete}
            disabled={cart.length === 0}
            className="w-full bg-slate-900 hover:bg-black text-white py-3 md:py-4 rounded-xl md:rounded-2xl font-black flex items-center justify-center gap-2 transition-all disabled:opacity-20 text-sm md:text-base"
          >
            Confirmar Cobro <CheckCircle2 className="w-5 h-5 md:w-6 md:h-6 text-emerald-400"/>
          </button>
        </div>
      </div>

      {/* Mobile Cart Trigger */}
      {!isCartMobileOpen && cart.length > 0 && (
        <button 
          onClick={() => setIsCartMobileOpen(true)}
          className="lg:hidden fixed bottom-24 left-1/2 -translate-x-1/2 z-[75] bg-slate-900 text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-10"
        >
          <div className="bg-emerald-500 text-white text-[10px] font-black w-5 h-5 rounded-full flex items-center justify-center">
            {cart.length}
          </div>
          <span className="text-sm font-bold">Ver Carrito</span>
          <span className="text-emerald-400 font-black">${total.toFixed(0)}</span>
          <ChevronUp className="w-4 h-4" />
        </button>
      )}
    </div>
  );
};

export default PosSystem;

import React, { useState } from 'react';
import { 
  Plus, Edit2, Trash2, Search, X, Pill, 
  Package, AlertTriangle, Calendar, Activity, 
  ShieldCheck, Save, Image as ImageIcon, 
  FileText, Hash, DollarSign, ChevronRight 
} from 'lucide-react';
import { Medication, Category, Batch } from '../types';

interface InventoryManagerProps {
  medications: Medication[];
  onAdd: (med: Medication) => void;
  onUpdate: (med: Medication) => void;
  onDelete: (id: string) => void;
}

const InventoryManager: React.FC<InventoryManagerProps> = ({ medications, onAdd, onUpdate, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingMed, setEditingMed] = useState<Medication | null>(null);

  const [formData, setFormData] = useState<Partial<Medication>>({
    name: '',
    genericName: '',
    laboratory: '',
    description: '',
    priceBox: 0,
    priceUnit: 0,
    unitsPerBox: 1,
    category: Category.OTHERS,
    imageUrl: 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?q=80&w=400',
    stockBoxes: 0,
    stockUnits: 0,
    isControlled: false,
    minStock: 5,
    batches: [{ lotNumber: '', expiryDate: '', quantity: 0 }]
  });

  const filtered = medications.filter(m => 
    m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.genericName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const openAddModal = () => {
    setEditingMed(null);
    setFormData({
      name: '', genericName: '', laboratory: '', description: '',
      priceBox: 0, priceUnit: 0, unitsPerBox: 1,
      category: Category.OTHERS, imageUrl: 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?q=80&w=400',
      stockBoxes: 0, stockUnits: 0, isControlled: false, minStock: 5,
      batches: [{ lotNumber: 'L-' + Math.floor(Math.random() * 9000), expiryDate: '', quantity: 0 }]
    });
    setIsModalOpen(true);
  };

  const openEditModal = (med: Medication) => {
    setEditingMed(med);
    setFormData(med);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalMed: Medication = { ...formData as Medication, id: editingMed ? editingMed.id : Date.now().toString() };
    if (editingMed) onUpdate(finalMed); else onAdd(finalMed);
    setIsModalOpen(false);
  };

  const getExpiryStatus = (expiryDate: string) => {
    if (!expiryDate) return { label: 'N/A', color: 'bg-slate-300' };
    const today = new Date();
    const expiry = new Date(expiryDate);
    const diffDays = Math.ceil((expiry.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays < 0) return { label: 'Vencido', color: 'bg-rose-500' };
    if (diffDays < 90) return { label: 'Próximo', color: 'bg-amber-500' };
    return { label: 'OK', color: 'bg-emerald-500' };
  };

  return (
    <div className="p-4 md:p-8 bg-slate-50 min-h-full pb-28 md:pb-12">
      <div className="max-w-7xl mx-auto">
        <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 flex items-center gap-2">
              <Package className="text-emerald-600 w-6 h-6 md:w-8 md:h-8"/> Existencias
            </h1>
            <p className="text-slate-400 text-xs md:text-sm font-medium">Control de lotes y trazabilidad.</p>
          </div>
          <div className="flex flex-col xs:flex-row gap-3">
            <div className="relative flex-1">
              <input 
                type="text" 
                placeholder="Buscar..." 
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500/20 shadow-sm text-sm"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400"/>
            </div>
            <button 
              onClick={openAddModal}
              className="bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-emerald-600/20 text-sm whitespace-nowrap"
            >
              <Plus className="w-4 h-4"/> Nuevo
            </button>
          </div>
        </header>

        <div className="grid grid-cols-1 gap-4">
          {filtered.map(med => (
            <div key={med.id} className="bg-white rounded-2xl md:rounded-3xl p-4 md:p-6 border border-slate-200 shadow-sm hover:border-emerald-200 transition-colors flex flex-col md:flex-row gap-4 md:gap-8 items-start md:items-center relative">
              <div className="flex items-center gap-4 w-full md:w-auto md:min-w-[280px]">
                <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-50 rounded-xl md:rounded-2xl flex items-center justify-center border border-slate-100 shrink-0 overflow-hidden">
                  <img src={med.imageUrl} alt="" className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-base md:text-lg font-black text-slate-800 truncate">{med.name}</h3>
                  <p className="text-[10px] md:text-xs text-slate-400 italic truncate">{med.genericName}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6 w-full flex-1 border-t md:border-t-0 pt-4 md:pt-0">
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-0.5 md:mb-1">Precio Unit</span>
                  <span className="text-sm md:text-base font-black text-slate-800">${med.priceUnit}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-0.5 md:mb-1">Existencia</span>
                  <div className="flex items-center gap-2">
                    <span className={`text-sm md:text-base font-black ${med.stockBoxes <= med.minStock ? 'text-rose-600' : 'text-slate-800'}`}>
                      {med.stockBoxes} C / {med.stockUnits} U
                    </span>
                  </div>
                </div>
                <div className="hidden lg:flex flex-col">
                  <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-1">Laboratorio</span>
                  <span className="text-xs font-bold text-slate-600 truncate">{med.laboratory}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-1">Vencimiento</span>
                  <div className="flex items-center gap-1.5">
                    <div className={`w-2 h-2 rounded-full ${getExpiryStatus(med.batches[0]?.expiryDate).color}`} />
                    <span className="text-xs font-bold text-slate-600">{med.batches[0]?.expiryDate || 'N/A'}</span>
                  </div>
                </div>
              </div>

              <div className="flex gap-2 w-full md:w-auto border-t md:border-t-0 pt-4 md:pt-0 justify-end">
                <button 
                  onClick={() => openEditModal(med)}
                  className="p-2.5 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg md:rounded-xl transition-all border border-slate-100 flex items-center justify-center"
                >
                  <Edit2 className="w-4 h-4"/>
                </button>
                <button 
                  onClick={() => onDelete(med.id)}
                  className="p-2.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg md:rounded-xl transition-all border border-slate-100 flex items-center justify-center"
                >
                  <Trash2 className="w-4 h-4"/>
                </button>
              </div>
            </div>
          ))}
        </div>

        {/* Modal Adaptativo */}
        {isModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center bg-slate-900/60 backdrop-blur-sm p-0 md:p-4 animate-in fade-in slide-in-from-bottom-10 duration-300">
            <div className="bg-white w-full max-w-4xl md:rounded-[2.5rem] shadow-2xl overflow-hidden flex flex-col h-[90vh] md:h-auto md:max-h-[90vh]">
              <div className="p-6 md:p-8 bg-slate-900 text-white flex justify-between items-center shrink-0">
                <h2 className="text-xl md:text-2xl font-black">{editingMed ? 'Editar' : 'Nuevo Producto'}</h2>
                <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-full">
                  <X className="w-6 h-6" />
                </button>
              </div>

              <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 md:p-8 space-y-6 md:space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                  <InputGroup label="Nombre" value={formData.name} onChange={v => setFormData({...formData, name: v})} />
                  <InputGroup label="Genérico" value={formData.genericName} onChange={v => setFormData({...formData, genericName: v})} />
                  <InputGroup label="Laboratorio" value={formData.laboratory} onChange={v => setFormData({...formData, laboratory: v})} />
                  <div className="flex flex-col gap-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Categoría</label>
                    <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm font-medium">
                      {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 bg-slate-50 p-4 md:p-6 rounded-2xl md:rounded-3xl border border-slate-100">
                  <InputGroup label="Precio Caja" type="number" value={formData.priceBox?.toString()} onChange={v => setFormData({...formData, priceBox: parseFloat(v)})} />
                  <InputGroup label="Uds x Caja" type="number" value={formData.unitsPerBox?.toString()} onChange={v => setFormData({...formData, unitsPerBox: parseInt(v)})} />
                  <InputGroup label="Stock Caja" type="number" value={formData.stockBoxes?.toString()} onChange={v => setFormData({...formData, stockBoxes: parseInt(v)})} />
                  <InputGroup label="Lote" value={formData.batches?.[0]?.lotNumber} onChange={v => {
                    const b = [...(formData.batches || [])]; b[0] = {...b[0], lotNumber: v}; setFormData({...formData, batches: b});
                  }} />
                </div>

                <div className="flex flex-col md:flex-row gap-4 pt-4">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="w-full md:flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl text-sm uppercase tracking-widest">Cancelar</button>
                  <button type="submit" className="w-full md:flex-[2] py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl shadow-emerald-600/30 text-sm uppercase tracking-widest">Guardar Cambios</button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const InputGroup = ({ label, value, onChange, type = "text" }: any) => (
  <div className="flex flex-col gap-1">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type} value={value} onChange={e => onChange(e.target.value)}
      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500/20 text-sm font-medium" 
    />
  </div>
);

export default InventoryManager;

import React from 'react';
import { TrendingUp, AlertTriangle, Calendar, Package } from 'lucide-react';
import { Medication } from '../types';

interface DashboardProps {
  medications: Medication[];
}

const Dashboard: React.FC<DashboardProps> = ({ medications }) => {
  const lowStock = medications.filter(m => m.stockBoxes <= m.minStock);
  const expiringSoon = medications.filter(m => {
    const expiry = new Date(m.batches[0]?.expiryDate);
    const diff = expiry.getTime() - new Date().getTime();
    return diff < (90 * 24 * 60 * 60 * 1000);
  });

  return (
    <div className="p-4 md:p-8 space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20 md:pb-8">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
